# the pointer, which stays on the terminal.
x, y = mouse_x + gap, mouse_y - gap - height
if y < 0:
    y = mouse_y + gap
if x + width > screen_width:
    x = mouse_x - gap - width
x = max(0, min(x, screen_width - width))
y = max(0, min(y, screen_height - height))
